// Extrai os comentários novos do payload da Meta.
// Ignora comentários da própria conta (evita loops quando o bot responde).
const OWN_USERNAMES = ['o-teu-canal', 'a_tua_conta', 'segunda_conta'];
const out = [];
for (const item of $input.all()) {
  const body = item.json.body || {};
  for (const entry of body.entry || []) {
    for (const ch of entry.changes || []) {
      if (ch.field !== 'comments') continue;
      const v = ch.value || {};
      const from = v.from || {};
      if (!v.id || !v.media || !v.media.id) continue;
      if (from.id === entry.id) continue;
      if (OWN_USERNAMES.includes((from.username || '').toLowerCase())) continue;
      out.push({ json: {
        igUserId: entry.id,
        commentId: v.id,
        mediaId: v.media.id,
        texto: v.text || '',
        username: from.username || ''
      }});
    }
  }
}
return out;

// Decide que link mandar, conforme o reel comentado.
// 0) tabela automática (webhook 'Registar publicação')
// 1) pelo ID/código do reel (POR_REEL)
// 2) produtos: palavra no comentário ou na legenda do reel (POR_PRODUTO). Funciona sem mediaId,
//    por isso um reel publicado à mão com "Comenta PIGGY" fica ligado sozinho.
// 3) Reels sem correspondência recebem o link do repositório (índice de todos os vídeos).
const POR_REEL = {
  // EXEMPLO: o ID do reel (aparece no evento do comentario) -> o que mandar.
  'ID_DE_UM_REEL': { nome: 'o projeto do video', url: 'https://o-teu-site.exemplo/go/projeto/' },
  'ID_DE_OUTRO_REEL': { tipo: 'guia', nome: 'o guia completo', url: 'https://o-teu-site.exemplo/go/guia/' },
};
// Produtos da loja. url = página de FUNIL /go/<slug> (publicar/funil.json), nunca a página do produto.
// palavra = a palavra do CTA ("Comenta PIGGY"), em minúsculas.
// abertura = fim da frase do DM de abertura; titulo/sub/botao = cartão final com o link.
const POR_PRODUTO = [
  // EXEMPLO: palavra do CTA ("Comenta GUIA") -> mensagem e link. Poe aqui os teus produtos.
  { palavra: 'guia', produto: true, nome: 'o guia',
    abertura: 'o link do guia 📘',
    titulo: 'Aqui esta o guia 👇', sub: 'Uma frase curta sobre o que a pessoa ganha.',
    botao: 'Ver o guia', url: 'https://o-teu-site.exemplo/go/guia/' },
];
// Variantes por tipo de reel (spec MON-503, documento interno).
// {nome} = @username do comentário; sem username tratável, só as frases sem {nome}.
const RESPOSTAS = {
  repositorio: [
    'Enviei-te o repositório por DM 🔧',
    'Repositório a caminho das tuas mensagens',
    'Já tens o repositório no DM 👀',
    'Manda uma vista de olhos às mensagens, repositório enviado',
    '{nome}, o repositório já está no DM 🚀',
    'Repositório enviado, bom proveito',
    'Está nas mensagens: o repositório 📩',
    'Mandei-te o link do repositório, vê os DMs',
    '{nome}, repositório a caminho 👀',
    'Repositório despachado por mensagem',
    'Vai ver os DMs, o repositório já lá está 🔧',
    '{nome}, repositório enviado por mensagem',
  ],
  guia: [
    'Enviei-te o guia por DM 📩',
    'O guia já está nas tuas mensagens',
    'Mandei-te o passo a passo, vê os DMs 👀',
    'Guia a caminho das mensagens',
    '{nome}, o guia já está no DM 🛡️',
    'Está feito, guia enviado por mensagem',
    'Guia enviado, bom proveito 🔧',
    'Vai às mensagens, o guia já lá está',
    '{nome}, guia a caminho 👀',
    'Mandei o passo a passo por DM',
    'Guia despachado, está nas mensagens 📩',
    'Está no DM: o guia completo',
  ],
  produto: [
    'Mandei-te o link por DM 🐷',
    'Já tens tudo nas mensagens',
    'Enviei o link do produto por DM 👀',
    'Está no DM, bom proveito',
    '{nome}, o link já está nas mensagens 📩',
    'Despachado por mensagem',
    'Link enviado, vê os DMs 🔧',
    '{nome}, já tens o link no DM',
    'Mandei por mensagem, espreita os DMs 👀',
    'Está feito: link enviado',
    '{nome}, link a caminho 📩',
    'Enviado por DM, bom proveito',
  ],
  noticia: [
    'Mandei-te a fonte por DM 📩',
    'Já tens o link nas mensagens',
    'Enviei-te o artigo por DM 👀',
    'Está no DM, a fonte completa',
    '{nome}, a notícia já está nas mensagens 🔗',
    'Despachado: link da fonte',
    'Mandei o link oficial por mensagem 📩',
    '{nome}, já tens tudo no DM',
    'Enviei por mensagem, vê os DMs 👀',
    'Está feito, fonte enviada',
    '{nome}, link a caminho 🔗',
    'Fonte enviada por DM',
  ],
};
// 'link' (índice, loja, Blender, jogos): só as frases neutras do produto, sem 🐷 nem «produto».
RESPOSTAS.link = RESPOSTAS.produto.filter(r => !/🐷|produto/.test(r));
const ABERTURAS = [
    'Boa! 👋',
    'Obrigado pelo comentário.',
    'Chegou a tua vez 👀',
    'Aqui tens.',
    'Boa escolha comentar isto.',
    'Então, vamos a isto 🚀',
];
// MON-504: nunca repete a última de cada lista (static data do workflow, 'ultimas').
const ultimas = (g => g.ultimas || (g.ultimas = {}))($getWorkflowStaticData('global'));
const sorteia = (xs, chave) => {
  const op = xs.length > 1 ? xs.filter(x => x !== ultimas[chave]) : xs;
  return (ultimas[chave] = op[Math.floor(Math.random() * op.length)]);
};
const resposta = (alvo, username) => {
  const tipo = alvo.tipo || (alvo.produto || alvo.funil ? 'produto' : 'repositorio');
  let xs = (RESPOSTAS[tipo] || RESPOSTAS.link).concat(alvo.respostas || []);
  if (!/piggy/i.test(alvo.nome || '')) xs = xs.filter(r => !r.includes('🐷'));
  const u = /^[a-z0-9._]{1,30}$/i.test(username || '') ? '@' + username : '';
  if (!u) xs = xs.filter(r => !r.includes('{nome}'));
  return sorteia(xs, tipo).replace('{nome}', u);
};
// Mensagens da MON-273 (documento "entrega"). PALAVRA é trocada pela palavra do vídeo.
const FUNIL = {
  generico: 'Boa! Se quiseres o pack que uso para isto, comenta PALAVRA que te mando o link.',
  como: 'Tenho isso num pack pronto, sem complicação. Comenta PALAVRA e mando-te o link por DM.',
  tecnica: 'Dá trabalho a primeira vez, sim. Fiz um pack passo a passo para isto, comenta PALAVRA e envio-te o link.',
  preco: 'É um pack único, pagas uma vez e é teu. Comenta PALAVRA e vês o preço e o que vem no link.',
  dm: 'Aqui tens o link: LINK\n\nBom proveito!',
};
const tipoComentario = t =>
  /pago|preco|quanto|custa|valor|caro|gratis|borla|euros|€/.test(t) ? 'preco'
  : /nao sei|nao consigo|configur|instal|trabalho|dificil|complicad|erro|nao funciona/.test(t) ? 'tecnica'
  : /como|onde|consigo|arranj|tutorial|ensina|quero|link/.test(t) ? 'como'
  : 'generico';
const temPalavra = (t, p) => new RegExp('(^|[^a-z0-9])' + p + '([^a-z0-9]|$)').test(t);
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

const posts = $input.all();
const out = [];
posts.forEach((p, i) => {
  const c = $('Extrair comentários').itemMatching(i).json;
  const permalink = p.json.permalink || '';
  const legenda = norm(p.json.caption);
  const texto = norm(c.texto);
  let alvo = null;
  // 0) Tabela automática, preenchida pelo webhook 'Registar publicação' (static data do workflow).
  const auto = (($getWorkflowStaticData('global').links) || {})[c.mediaId];
  if (auto && auto.url) alvo = { nome: auto.nome, url: auto.url, tipo: auto.tipo };
  if (!alvo) for (const [codigo, v] of Object.entries(POR_REEL)) if (permalink.includes(codigo) || c.mediaId === codigo) alvo = v;
  // Reel registado ou em POR_REEL com «Comenta PALAVRA» de um produto do funil: aplica a regra
  // do funil com o link desse vídeo (MON-279; os reels do pipeline chegam todos registados).
  const funilLeg = POR_PRODUTO.find(v => v.funil && new RegExp('comenta\\W+' + v.palavra + '([^a-z0-9]|$)').test(legenda));
  if (alvo && funilLeg) alvo = { ...funilLeg, url: alvo.url };
  // MON-300: comentário que é só a palavra de outro produto do funil (CHECKLIST num reel do PLAYBOOK) leva esse produto.
  const exata = POR_PRODUTO.find(v => v.funil && texto.replace(/[^a-z0-9]/g, '') === v.palavra);
  if (exata && (!alvo || alvo.palavra !== exata.palavra)) alvo = exata;
  if (!alvo) alvo = POR_PRODUTO.find(v => v.funil || v.inteira
    ? new RegExp('comenta\\W+' + v.palavra + '([^a-z0-9]|$)').test(legenda) || texto.replace(/[^a-z0-9]/g, '') === v.palavra
    : texto.includes(v.palavra) || legenda.includes(v.palavra)) || null;
  // Reel sem correspondência: manda o índice com os links de todos os vídeos
  // MON-312 + regra de separação de canais: na segunda_conta só o funil; o resto não tem resposta.
  if (c.igUserId === 'ID_DA_SEGUNDA_CONTA' && !(alvo && alvo.funil)) return;
  if (!alvo) alvo = { tipo: 'link', nome: 'os links de todos os vídeos', url: 'https://o-teu-site.exemplo/go/' };  // funil (2026-10-17)
  if (alvo.funil) {
    const P = alvo.palavra.toUpperCase();
    if (!temPalavra(texto.replace(/-/g, ''), alvo.palavra)) {
      // Sem a palavra: só a resposta pública a convidar, nunca o link, sem DM.
      out.push({ json: { ...c, permalink, publica: FUNIL[tipoComentario(texto)].replace('PALAVRA', P), enviarDm: false } });
      return;
    }
    const publica = resposta(alvo, c.username);
    out.push({ json: { ...c, permalink, publica, enviarDm: true, mensagem: { text: sorteia(ABERTURAS, 'abertura') + '\n\n' + FUNIL.dm.replace('LINK', alvo.url) } } });
    return;
  }
  const publica = resposta(alvo, c.username);
  // DM de abertura (igual ao ManyChat): texto + botão "Quero o link".
  // O destino vai escondido no payload do botão.
  const payload = 'LINK|' + JSON.stringify({ n: alvo.nome, u: alvo.url, l: alvo.lista || '', t: alvo.titulo || '', s: alvo.sub || '', b: alvo.botao || '' });
  const mensagem = {
    text: `${sorteia(ABERTURAS, 'abertura')}\n\nCarrega no botão e envio-te já ${alvo.abertura || alvo.nome + ' 🚀'}`,
    quick_replies: [{ content_type: 'text', title: 'Quero o link 🔗', payload }],
  };
  out.push({ json: { ...c, permalink, publica, enviarDm: true, mensagem } });
});
return out;

// Quando a pessoa carrega em "Quero o link", o Instagram manda um evento de mensagem.
// Aqui apanhamos esse clique e preparamos a mensagem final com o botão do link.
const SITE = 'https://o-teu-site.exemplo/go/';  // regra do funil (nunca o link direto); MON-503
const out = [];
for (const item of $input.all()) {
  const body = item.json.body || {};
  for (const entry of body.entry || []) {
    if (entry.id === 'ID_DA_SEGUNDA_CONTA') continue;  // MON-312: o botão e o follow-up são só da @a_tua_conta
    for (const ev of entry.messaging || []) {
      // 02/11: a Meta passou a mandar o clique em "Quero o link" como eco (sender = nós, recipient = a pessoa).
      const eco = !!(ev.message && ev.message.is_echo);
      if (eco && !(ev.message.quick_reply && ev.message.quick_reply.payload)) continue;  // eco das nossas mensagens
      const p = (ev.message && ev.message.quick_reply && ev.message.quick_reply.payload)
             || (ev.postback && ev.postback.payload) || '';
      if (!p.startsWith('LINK|')) continue;
      let alvo;
      try { alvo = JSON.parse(p.slice(5)); } catch (e) { continue; }
      let mensagem;
      if (alvo.l) {
        mensagem = { text: `Aqui estão ${alvo.n} 👇\n\n${alvo.l}` };
      } else {
        mensagem = { attachment: { type: 'template', payload: {
          template_type: 'generic',
          elements: [{
            title: (alvo.t || `Aqui está ${alvo.n} 👇`).slice(0, 80),
            ...(alvo.s ? { subtitle: alvo.s.slice(0, 80) } : {}),
            buttons: [{ type: 'web_url', url: alvo.u,
                        title: alvo.b || (alvo.u.includes('github.com') ? 'Abrir no GitHub' : 'Abrir o link') }],
          }],
        }}};
      }
      // Mensagem enviada 5 minutos depois (a janela de 24h está aberta porque a pessoa carregou no botão).
      const followup = { attachment: { type: 'template', payload: {
        template_type: 'generic',
        elements: [{
          title: 'Gostaste? 🙌',
          subtitle: 'Segue a @a_tua_conta para mais IA, homelab e automação. E vê os links de todos os vídeos.',
          buttons: [
            { type: 'web_url', url: 'https://www.instagram.com/a_tua_conta', title: 'Seguir no Instagram' },
            { type: 'web_url', url: SITE, title: 'Ver todos os links' },
          ],
        }],
      }}};
      const pessoa = eco ? (ev.recipient && ev.recipient.id) : (ev.sender && ev.sender.id);
      if (!pessoa || pessoa === entry.id) continue;
      const visto = $getWorkflowStaticData('global');  // o mesmo clique pode chegar pelas duas vias: link só 1 vez
      visto.cliques = visto.cliques || {};
      const chave = pessoa + '|' + p, agora = Date.now();
      if (visto.cliques[chave] && agora - visto.cliques[chave] < 30 * 60 * 1000) continue;
      visto.cliques[chave] = agora;
      for (const [k, t] of Object.entries(visto.cliques)) if (agora - t > 24 * 3600 * 1000) delete visto.cliques[k];
      out.push({ json: { igUserId: entry.id, senderId: pessoa, mensagem, followup } });
    }
  }
}
return out;

// Recebe do agente que publicou (Composio + Zernio) os dados do vídeo.
// Body esperado (JSON): { segredo, dm_nome, dm_url, legenda?, titulo?, media_id?, permalink? }
// Basta UM de: media_id, permalink ou legenda. Sem segredo certo, não faz nada.
const SEGREDO = 'TROCA_PELO_TEU_SEGREDO';
const out = [];
for (const item of $input.all()) {
  const b = item.json.body || {};
  if ((b.segredo || '') !== SEGREDO) continue;
  if (!b.dm_url) continue;
  const legenda = String(b.legenda || b.titulo || '').trim();
  out.push({ json: {
    media_id: b.media_id ? String(b.media_id) : '',
    permalink: String(b.permalink || ''),
    legenda,
    titulo: String(b.titulo || ''),
    dm_nome: String(b.dm_nome || 'o link do vídeo'),
    dm_url: String(b.dm_url),
    recebido_em: new Date().toISOString(),
  }});
}
return out;

// Procura, nos últimos reels da conta, o que corresponde ao vídeo registado.
// Ordem: media_id > código do permalink > legenda (início da legenda, sem acentos nem espaços a mais).
// Se encontrar, grava media_id -> {nome, url} na tabela automática que o nó "Escolher link" lê.
const reg = $('Preparar registo').first().json;
const tentativa = $runIndex + 1;
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ').trim();
const codigo = p => { const m = String(p || '').match(/\/(?:reel|p|reels)\/([A-Za-z0-9_-]+)/); return m ? m[1] : ''; };
const resp = $input.first().json || {};
const lista = resp.data ? resp.data : (resp.id ? [resp] : []);
const alvoCodigo = codigo(reg.permalink);
const alvoLegenda = norm(reg.legenda).slice(0, 80);
let achado = null;
for (const m of lista) {
  if (reg.media_id && String(m.id) === reg.media_id) { achado = m; break; }
  if (alvoCodigo && codigo(m.permalink) === alvoCodigo) { achado = m; break; }
  if (alvoLegenda.length >= 12) {
    const cap = norm(m.caption);
    if (cap.startsWith(alvoLegenda) || cap.includes(alvoLegenda)) { achado = m; break; }
  }
}
if (!achado) {
  return [{ json: { encontrado: false, tentativa, reels_vistos: lista.length, ...reg } }];
}
const s = $getWorkflowStaticData('global');
s.links = s.links || {};
s.links[String(achado.id)] = {
  nome: reg.dm_nome, url: reg.dm_url, titulo: reg.titulo,
  permalink: achado.permalink || '', publicado_em: achado.timestamp || '',
  registado_em: new Date().toISOString(),
};
return [{ json: { encontrado: true, tentativa, media_id: String(achado.id), permalink: achado.permalink || '', dm_nome: reg.dm_nome, dm_url: reg.dm_url, total_links: Object.keys(s.links).length } }];
